WITH lines AS (SELECT id, customer_id, created_at, pos + 1 AS position, entry.product_id, entry.qty, entry.price, entry.promo FROM carts LATERAL VIEW POSEXPLODE(items) e AS pos, entry) SELECT DATE_TRUNC('DAY', created_at) AS activity_day, CASE WHEN product_id >= 11 THEN 'PREMIUM' ELSE 'STANDARD' END AS product_id_tier, CASE WHEN position >= 3 THEN 'LARGE' ELSE 'SMALL' END AS position_tier, COUNT(*) AS event_count, COUNT_IF(promo = 'SPRING10') AS spring10_events, MAX(created_at) AS ended_at, GROUPING(DATE_TRUNC('DAY', created_at)) AS grouping_id FROM lines GROUP BY GROUPING SETS ((DATE_TRUNC('DAY', created_at), CASE WHEN product_id >= 11 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN position >= 3 THEN 'LARGE' ELSE 'SMALL' END), (DATE_TRUNC('DAY', created_at), CASE WHEN product_id >= 11 THEN 'PREMIUM' ELSE 'STANDARD' END), (DATE_TRUNC('DAY', created_at)), ());
